#!/bin/bash
# Heap guard for crawl boxes box1 (v2) and box5: src/heapGuard.js (new) + standalone.js + scripts/run-daily-crawl.mjs.
# Self-contained: the patches and heapGuard.js are embedded below, so `check` stages nothing on the box. Run ON the box from STDIN:
#
#   ssh box1 'bash -s -- check'    < install.sh     # READ-ONLY on the crawler: gates, md5s, zero-fuzz trial on copies in a mktemp dir (removed on exit)
#   ssh box1 'bash -s -- apply'    < install.sh     # check, backup, install, verify; restores itself on any failure
#   ssh box1 'bash -s -- restore'  < install.sh     # put the backed-up files back, remove heapGuard.js
#
# REFUSES (exit 1, nothing written) on: a crawl/sync running, 21:30-07:00 ET, a file whose md5 is not a known state.
# No restart, no cron or env change: the next crawl is a fresh Node process. The heap guard is on by default (0.85 of the heap limit);
# CRAWLER_HEAP_GUARD_RATIO=0 turns it off. Raising a heap limit is a separate, optional step (STEPS.md).
set -u
C=${HEAPGUARD_CRAWLER_DIR:-/home/ubuntu/nj-scraper/scrapers/lightsail-crawler}
BK=${HEAPGUARD_BACKUP:-/home/ubuntu/backups/heap-guard-20261106}
SRC=$C/src; DRV=$C/scripts/run-daily-crawl.mjs; SA=$SRC/standalone.js; HG=$SRC/heapGuard.js
HG_MD5=4f7b10d7a809816d78207c18d4634e01
# Known "before" states: box label, standalone.js md5, driver md5, and what the patches must produce.
B1_SA=8c39cf86d3017210d586ff3afeb33969;  B1_DR=89b6bb521c564bd2fb2f564f91f135b3;  B1_SA_AFTER=5d9fd12d7ed1f3be285bdef03853003e;  B1_DR_AFTER=479661a3b44161cc0632aff44d8b48e3
B5_SA=2e69d8748b9addbff93dac618bb71f1e;  B5_DR=f3d6c4b508e94b067a3a817b55675b70;  B5_SA_AFTER=57567be2152e42cd2fc6776f312a98cf;  B5_DR_AFTER=1b4ce62b7d0884f3f4b473974b2533cf

fail() { echo "REFUSED: $*" >&2; exit 1; }
md5of() { md5sum "$1" | cut -d' ' -f1; }
MODE=${1:-check}

if [ "$MODE" = restore ]; then
  [ -f "$BK/md5s-before.txt" ] || fail "no backup at $BK"
  for f in standalone.js run-daily-crawl.mjs; do
    want=$(awk -v f=$f '$2==f{print $1}' "$BK/md5s-before.txt"); [ "$(md5of "$BK/$f.before")" = "$want" ] || fail "backup $f does not match its recorded md5"
  done
  cp -p "$BK/standalone.js.before" "$SA.rb" && mv -f "$SA.rb" "$SA"
  cp -p "$BK/run-daily-crawl.mjs.before" "$DRV.rb" && mv -f "$DRV.rb" "$DRV"
  rm -f "$HG"
  echo "restored: standalone.js $(md5of "$SA"), run-daily-crawl.mjs $(md5of "$DRV"), heapGuard.js removed"; exit 0
fi
[ "$MODE" = check ] || [ "$MODE" = apply ] || fail "mode must be check, apply or restore (got '$MODE')"

now=$(TZ=America/New_York date +%H%M)
if [ $((10#$now)) -ge 2130 ] || [ $((10#$now)) -lt 700 ]; then fail "it is $now ET: installs only 07:00-21:30 ET (crons start at 22:00)"; fi
busy=$( { pgrep -a -x node | grep -E 'src/standalone|inventory-sync|run-daily-crawl'; pgrep -af '^(/bin/|/usr/bin/)?bash [^ ]*(run-daily-crawl|run_nightly_chain|run_sync_when_safe)'; } 2>/dev/null | grep -v pgrep )
[ -z "$busy" ] || fail "a crawl or sync is running: $busy"
for f in "$SA" "$DRV"; do [ -f "$f" ] || fail "$f not found (wrong box or path)"; done
node -e 'process.exit(typeof structuredClone==="function"?0:1)' || fail "this node has no structuredClone ($(node -v))"

sa=$(md5of "$SA"); dr=$(md5of "$DRV"); BOX=
case "$sa:$dr" in
  "$B1_SA:$B1_DR") BOX=b1; SA_AFTER=$B1_SA_AFTER; DR_AFTER=$B1_DR_AFTER; echo "box1 variant (standalone $sa, driver $dr)";;
  "$B5_SA:$B5_DR") BOX=b5; SA_AFTER=$B5_SA_AFTER; DR_AFTER=$B5_DR_AFTER; echo "box5 variant (standalone $sa, driver $dr)";;
  "$B1_SA_AFTER:$B1_DR_AFTER"|"$B5_SA_AFTER:$B5_DR_AFTER") [ -f "$HG" ] && [ "$(md5of "$HG")" = "$HG_MD5" ] && { echo "ALREADY INSTALLED, nothing to do."; exit 0; }; fail "files are patched but heapGuard.js is missing or not the pinned file";;
  *) fail "standalone.js md5 $sa / run-daily-crawl.mjs md5 $dr is not a known state (box1 $B1_SA/$B1_DR, box5 $B5_SA/$B5_DR). Send the files back; do not improvise.";;
esac
[ ! -e "$HG" ] || [ "$(md5of "$HG")" = "$HG_MD5" ] || fail "$HG exists with an unexpected md5"

W=$(mktemp -d /tmp/heapguard-trial.XXXXXX) || fail "cannot make a temp dir"
trap 'rm -rf "$W"' EXIT
mkdir -p "$W/src" "$W/scripts"
emit_hg()      { base64 -d <<'HGEOF'

HGEOF
}
emit_sa_b1()   { base64 -d <<'EOF1'

EOF1
}
emit_sa_b5()   { base64 -d <<'EOF2'

EOF2
}
emit_dr_b1()   { base64 -d <<'EOF3'

EOF3
}
emit_dr_b5()   { base64 -d <<'EOF4'

EOF4
}
emit_hg > "$W/src/heapGuard.js"; [ "$(md5of "$W/src/heapGuard.js")" = "$HG_MD5" ] || fail "embedded heapGuard.js md5 wrong"
emit_sa_$BOX > "$W/sa.patch"; emit_dr_$BOX > "$W/dr.patch"
cp -p "$SA" "$W/src/standalone.js"; cp -p "$DRV" "$W/scripts/run-daily-crawl.mjs"
(cd "$W" && patch -p1 -s -F0 --no-backup-if-mismatch < sa.patch) || fail "standalone patch does not apply (zero fuzz)"
(cd "$W" && patch -p1 -s -F0 --no-backup-if-mismatch < dr.patch) || fail "driver patch does not apply (zero fuzz)"
m=$(md5of "$W/src/standalone.js"); [ "$m" = "$SA_AFTER" ] || fail "patched standalone.js md5 $m, expected $SA_AFTER"
m=$(md5of "$W/scripts/run-daily-crawl.mjs"); [ "$m" = "$DR_AFTER" ] || fail "patched run-daily-crawl.mjs md5 $m, expected $DR_AFTER"
cp "$W/src/standalone.js" "$W/chk1.mjs"; node --check "$W/chk1.mjs" || fail "patched standalone.js does not parse"
cp "$W/scripts/run-daily-crawl.mjs" "$W/chk2.mjs"; node --check "$W/chk2.mjs" || fail "patched driver does not parse"
out=$(cd "$W/src" && node --input-type=module -e 'const m = await import("./heapGuard.js"); const g = m.makeHeapGuard({ratio:0.85, stats:()=>({used_heap_size:90,heap_size_limit:100}), minIntervalMs:0}); const c = m.detachStrings({a:"x",d:new Date(1)}); console.log(g.pressured(), c.a, c.d instanceof Date)' 2>&1)
[ "$out" = "true x true" ] || fail "heapGuard.js smoke test gave: $out"
echo "trial ok: standalone.js -> $SA_AFTER, run-daily-crawl.mjs -> $DR_AFTER, heapGuard.js smoke test ok"
if [ "$MODE" = check ]; then echo "CHECK only, nothing installed. Re-run with 'apply' on Paul's GO."; echo "ROLLBACK: rerun with 'restore' (bash -s -- restore < install.sh)."; exit 0; fi

[ ! -e "$BK/md5s-before.txt" ] || fail "$BK already holds a backup from an earlier run; move it aside first"
mkdir -p "$BK" || fail "cannot make $BK"
cp -p "$SA" "$BK/standalone.js.before"; cp -p "$DRV" "$BK/run-daily-crawl.mjs.before"
{ echo "$sa standalone.js"; echo "$dr run-daily-crawl.mjs"; } > "$BK/md5s-before.txt"
bad() { echo "FAILED: $*" >&2; cp -p "$BK/standalone.js.before" "$SA"; cp -p "$BK/run-daily-crawl.mjs.before" "$DRV"; rm -f "$HG"; echo "restored from $BK" >&2; exit 1; }
install -m 644 "$W/src/heapGuard.js" "$HG.new" && mv -f "$HG.new" "$HG" || bad "installing heapGuard.js"
cp -p "$W/src/standalone.js" "$SA.new" && mv -f "$SA.new" "$SA" || bad "installing standalone.js"
cp -p "$W/scripts/run-daily-crawl.mjs" "$DRV.new" && mv -f "$DRV.new" "$DRV" || bad "installing driver"
[ "$(md5of "$HG")" = "$HG_MD5" ] && [ "$(md5of "$SA")" = "$SA_AFTER" ] && [ "$(md5of "$DRV")" = "$DR_AFTER" ] || bad "md5 after install"
cp "$SA" "$W/f1.mjs"; node --check "$W/f1.mjs" || bad "installed standalone.js does not parse"
cp "$DRV" "$W/f2.mjs"; node --check "$W/f2.mjs" || bad "installed driver does not parse"
{ echo "$HG_MD5 heapGuard.js"; echo "$SA_AFTER standalone.js"; echo "$DR_AFTER run-daily-crawl.mjs"; } > "$BK/md5s-after.txt"
echo "INSTALLED. backup in $BK; md5s now:"; sed 's/^/  /' "$BK/md5s-after.txt"
echo "No restart: the next crawl is a fresh Node process. ROLLBACK: rerun with 'restore'."
